mapper.select:
SELECT v.video_id AS videoId, v.thumbnail_url AS thumbnailUrl, v.view_count AS viewCount, v.title AS title, v.video_url AS videoUrl, (SELECT COUNT(*) FROM comment cm WHERE cm.video_id = v.video_id AND cm.is_deleted = false) AS commentCount, (SELECT COUNT(*) FROM reaction r WHERE r.video_id = v.video_id) AS likeCount, (my_reaction.reaction_id IS NOT NULL) AS liked FROM video v LEFT JOIN category c ON v.category_id = c.category_id LEFT JOIN reaction my_reaction ON v.video_id = my_reaction.video_id AND my_reaction.user_id = #{userId}
INNER JOIN reaction r_filter ON v.video_id = r_filter.video_id AND r_filter.user_id = #{likedUserId}
INNER JOIN subscription sub ON v.category_id = sub.category_id AND sub.user_id = #{userId}
WHERE 1=1
AND c.category_name = #{categoryName}
AND v.category_id = #{categoryId}
AND v.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY
v.view_count DESC, v.created_at DESC
(SELECT COUNT(*) FROM reaction r WHERE r.video_id = v.video_id) DESC, v.created_at DESC
r_filter.created_at DESC
v.created_at DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE video
SET view_count = view_count + 1
WHERE video_id = #{videoId}
